Decorate a method with this attribute to register it as a handler for the  event.
The method must match the  delegate signature.

[MembersAddedRoute]
public async Task OnMembersAddedAsync(ITurnContext turnContext, ITurnState turnState, CancellationToken cancellationToken)
{
   foreach (ChannelAccount member in turnContext.Activity.MembersAdded)
   {
       if (member.Id != turnContext.Activity.Recipient.Id)
       {
           await turnContext.SendActivityAsync(MessageFactory.Text("Hello and Welcome!"), cancellationToken);
       }
   }
}

